from pathlib import Path
import json,html,re
P=Path(__file__).parent;D=P/'dist';D.mkdir(exist_ok=True)
if (D/'CNAME').exists():(D/'CNAME').unlink()
C=json.loads((P/'content.json').read_text(encoding='utf-8'));S=json.loads((P/'study.json').read_text(encoding='utf-8'));E=html.escape
def paras(xs):return ''.join('<p>'+E(x)+'</p>'for x in xs)
def card(a,b):return '<article class="small-card"><h3>'+E(a)+'</h3>'+paras([b])+'</article>'
chapters=[]
def section(id,label,title,body):
 chapters.append((id,label));return f'<section id="{id}" class="chapter"><div class="eyebrow">{len(chapters):02} / {E(label)}</div><h2>{title}</h2>{body}</section>'
def table(head,rows):return '<div class="table-wrap" tabindex="0" role="region" aria-label="可横向滚动的对照表"><table><thead><tr>'+''.join('<th>'+E(v)+'</th>'for v in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+E(v)+'</td>'for v in row)+'</tr>'for row in rows)+'</tbody></table></div>'
def flow(nodes):return '<div class="journey">'+''.join(('<i aria-hidden="true">→</i>'if n else '')+'<div><b>'+E(a)+'</b><br>'+E(b)+'</div>'for n,(a,b)in enumerate(nodes))+'</div>'
body=section('overview','敬拜与主旨','熟悉真理的人，<br>也需要让真理纠正自己','<div class="ribbon"><span>♫ 圣诗4首</span><span>韵诗11篇</span><span>韵诗7篇</span><span>韵诗1篇</span><span>♫ 圣诗9首</span><span>读经 箴言5章</span><span>证道 约7:45–52</span></div>'+paras([C['intro']])+'<blockquote>'+E(C['thesis'])+'</blockquote><div class="note"><b>本篇核心：</b>罪的荒谬是道德与属灵上的自相矛盾，不是智力羞辱或精神疾病标签。讲章先照见我们自己，再引我们信靠基督。</div><a class="text-link" href="sermon.html">打开独立连贯讲章版 →</a>')
body+=section('background','历史与写作背景','走进住棚节场景中的<br>这一次回报',''.join('<h3>'+E(a)+'</h3>'+paras([b])for a,b in C['background'])+table(['前后经文','叙事焦点','本段关联'],C['context'])+'<div class="note"><b>上下文的文本边界：</b>约7:53–8:11在重要早期抄本中缺载，在部分抄本中位置不同，现代译本常作括注。这里连接8:12的光主题，是按约翰全书主题相读，不据此强定52节之后的同日行程，也不把这段有文本讨论的叙事当作无争议的时间连接证据。<a href="https://learn.ligonier.org/devotionals/woman-caught-in-adultery" target="_blank" rel="noopener">背景说明 ↗</a></div>')
body+=section('text','八节经文与关键观察','同一场对话，<br>两次回避查验','<div class="scripture">'+''.join(f'<p><sup>{n}</sup>{E(t)}</p>'for n,t in C['verses'])+'</div><p class="caption">中文和合本（公共领域），按段落编排；没有以改写代替经文。<a href="https://www.biblegateway.com/passage/?search=John%207%3A45-52&version=CUVS" target="_blank" rel="noopener">原段阅读 ↗</a></p><div class="grid two">'+''.join(card(a,b)for a,b in C['exegesis'])+'</div>')
sermonHTML=paras([C['intro']])
for s in C['sermon']:
 part='<p class="subtitle">'+E(s['subtitle'])+'</p>'+paras(s['paragraphs'])+'<blockquote>'+E(s['line'])+'</blockquote>'
 body+=section(s['id'],s['title'],s['title'],part)
 sermonHTML+='<section class="sermon-part"><h2>'+E(s['title'])+'</h2>'+part+'</section>'
body+=section('wisdom','箴言5章的读经关联','嘴唇的甜，<br>不等于道路的善',table(['箴言5章','直接意义','与约7的关联'],[
 ['1–6节','听取父亲的智慧，辨别奸淫的诱惑；起初甜，至终苦。','罪使当下吸引力遮盖实际后果；宗教上的自保同样可能掩盖真相。'],['7–14节','远离不忠的道路，不把尊荣、年岁与劳力交给罪；结局回顾拒绝教训。','拒绝受教不是小事；我想保住的地位，可能正被我拒绝真理的方式败坏。'],['15–20节','在婚约中喜悦配偶，珍惜忠贞与亲密。','悔改不是只停止作恶，也转向神所赐的善；约7应用为重新爱真理与公义。'],['21–23节','神察看人的道路，罪如绳索缠绕人。','人可以堵住反对声音，却不能使自己不在神面前；自欺最终不能解除责任。']])+paras(['这两处经文主题相联，却不是同一件事：箴言5章直接谈婚姻忠贞，约翰7章直接记宗教领袖对见证与律法的回应。我们先尊重各段原意，再看见共同的自欺机制：为了眼前欲望或自我保护，拒绝神所显明的真相。','箴言把命令放在受教者面前，要求他为自己的选择负责。不能把所有女性描绘为危险，也不能把不忠归咎于配偶不够好。其婚姻伦理应用于男女双方：诚实、忠贞、尊重、远离诱惑，不以短暂享受合理化背约。对于已受伤的人，教会应陪伴、保护并追求公义，不把他人的犯罪或复杂苦难草率归罪于受害者。'])+'<blockquote>罪最会隐瞒的，常不是眼前的甜，而是它要你付出的代价。</blockquote><a href="https://www.biblegateway.com/passage/?search=Proverbs%205&version=CUVS" target="_blank" rel="noopener">完整读经：箴言5章 ↗</a>')
mapSVG='''<figure class="map"><div class="map-layout"><svg viewBox="0 0 650 600" role="img" aria-label="加利利、迦特希弗、耶路撒冷与伯利恒相对位置图"><rect width="650" height="600" rx="16" fill="#e9ece7"/><path d="M240 20Q210 150 215 260T175 580H620V20Z" fill="#d5cbb8"/><path d="M393 130Q402 230 400 320T421 480" stroke="#7da6a4" stroke-width="6" fill="none"/><ellipse cx="393" cy="125" rx="18" ry="32" fill="#7da6a4"/><ellipse cx="421" cy="480" rx="22" ry="62" fill="#7da6a4"/><text x="42" y="260" class="map-label">地中海</text><text x="445" y="130" class="map-label">加利利海</text><text x="465" y="485" class="map-label">死海</text><text x="250" y="70" class="region">加利利</text><text x="270" y="305" class="region">撒玛利亚</text><text x="265" y="520" class="region">犹太地区</text><circle cx="308" cy="170" r="7" fill="#507b76"/><path d="M308 170L245 191H205" fill="none" stroke="#507b76"/><text x="110" y="198" class="city">拿撒勒</text><circle cx="327" cy="155" r="7" fill="#995b44"/><path d="M327 155L365 185H430" fill="none" stroke="#995b44"/><text x="430" y="195" class="city">迦特希弗</text><circle cx="330" cy="424" r="7" fill="#684759"/><text x="350" y="429" class="city">耶路撒冷</text><circle cx="325" cy="458" r="6" fill="#537d67"/><text x="235" y="465" class="city">伯利恒</text><text x="35" y="558" class="map-label">N ↑</text></svg><div class="map-notes"><div class="eyebrow">地理事实与解释边界</div><h3>标签不能代替查考。</h3><p>约拿来自迦特希弗（王下14:25）；书19:13提供该地在西布伦境的线索。这里用后来加利利区域作说明，不把不同时代的行政边界机械等同。</p><div class="place-buttons"><button data-info="约拿的籍贯见王下14:25；书19:13把迦特希弗列在西布伦边界中。它为一般性的加利利无先知说法提出明确反证。">⌖ 约拿的籍贯</button><button data-info="耶稣与加利利有关，并不否定他在伯利恒出生；太2:1与路2:4–7提供正典互证。约翰更强调他由父差来（7:28–29）。">⌖ 耶稣的来处</button></div><p id="place-info" aria-live="polite">点选主题，查看经文证据。</p></div></div><figcaption>原创相对位置示意，非测绘地图。迦特希弗以常见定位区域概化；图中连接线是标签引线，不是行程路线。</figcaption></figure>'''
body+=section('map','地图与第52节难点','当“去查考”<br>已经预设了答案',mapSVG+'<div class="grid two">'+card('通常读法：没有出过先知','若理解为加利利从未出任何先知，约拿是清楚的经文反例。这个观察指出断言需要检验，却不让我们编造每位发言者是否忘记约拿的内心过程。')+card('文本讨论：那先知','NET译者注释提及早期抄本P66原读在先知前带冠词；部分解释据此或据上下文，联系申18的那先知。本文保留和合本正文，并提示这种讨论，不混合版本假装只有一个毫无争议的字义。')+'</div><p>两种理解之下都成立的重点是：52节的回应没有解决51节的公平听审问题。地域不是定罪证据，自信也不能免除查验。不要把整篇信息压在单一、仍有讨论的文本细节上。</p><p><a href="https://classic.net.bible.org/verse.php?book=Joh&chapter=7&verse=52" target="_blank" rel="noopener">NET 译者原注 ↗</a></p>')
body+=section('justice','论证对照与公义流程','先听，查实，<br>再按真理判断',table(['场景','应当处理的问题','实际的转移','今日自省'],[
 ['差役回报','耶稣说了什么，为何使他们震动？','先叫见证者受迷惑。','我是否用动机猜测代替听事实？'],['官长的身份','他们的判断是否有经文根据？','以谁没有信代替是否真实。','我是否把圈内共识看得高于圣经？'],['咒诅群众','不明白的人需要怎样受教？','以轻蔑排除整个群体。','我学得更多，是否也更愿服事？'],['尼哥底母提问','律法是否要求先听后断？','追问你是否出于加利利。','我是否攻击提问者而回避问题？'],['要求查考','断言是否经得起完整检验？','结论似乎已经不可修正。','我是否愿承认反例并调整判断？']])+flow([('先听','不抢答、不捏造'),('查实','让双方陈述'),('按圣言','同一标准约束自己'),('作判断','不因地位而偏待'),('肯纠正','事实更新便更正')])+'<p>经文互证：申1:16–17要求公平听案；申17:4要求细细探听；申19:15–19要求证据与查究；出23:1–3禁止随众作恶；箴18:13、17提醒未听先答与只听一方的危险。这些是51节原则的支持，不声称51节逐字引用了其中任何一句。</p><div class="discernment"><label><input type="checkbox"> 我能先完整复述对方观点，且对方会承认我没有歪曲。</label><label><input type="checkbox"> 我已区分事实、推论与对动机的猜测。</label><label><input type="checkbox"> 我要求对方接受的标准，也愿接受在自己身上。</label><label><input type="checkbox"> 若证据表明我错，我愿更正并向被伤害者道歉。</label><p id="discern-status" aria-live="polite">这不是给自己判义的评分，而是受教的起点。</p></div>')
body+=section('redemption','救赎历史的闭环','真理被拒绝，<br>救主却为罪人舍命',flow([('受造','思想为认识神'),('堕落','心为私欲辩护'),('应许','神赐拯救盼望'),('基督','真理进入历史'),('十架','担当罪与咒诅'),('圣灵','更新领受的心'),('终局','真光中见主面')])+'''<div class="timeline"><div><b>创1:26–28；3:1–15</b><span>人照神形像受造，却以自己的判断取代神；神主动赐下拯救应许。</span></div><div><b>申1:16–17；箴5；耶31:31–34</b><span>律法揭露不义，智慧揭露自毁，先知应许赦罪与心的更新。</span></div><div><b>约1:14、17；3:3–17；7:45–52</b><span>恩典与真理在耶稣里显明；人需要重生，不只是补充资料。</span></div><div><b>约10:17–18；18–19章；加3:13</b><span>无罪的主遭不公对待，却甘愿担当咒诅；罪由犯罪者负责，救赎出于神的圣洁旨意。</span></div><div><b>约20:19–23；16:8–14；弗4:20–25</b><span>复活与圣灵的工作把人带入真实生命，使心思更新，脱去谎言。</span></div><div><b>启22:3–5</b><span>咒诅不再有，神的百姓见他的面；人的受造目的在救赎中得恢复。</span></div></div><blockquote>救主不只使我更会回答问题，也使我愿意让真理回答我的心。</blockquote>''')
body+=section('covenant','圣约与罪—救赎—感恩','不靠自辩称义，<br>因蒙恩而敢认错','<div class="grid two">'+card('圣约闭环：应许 → 成全 → 领受 → 顺服','圣约群体真实领受神的话与恩惠，也真实被呼召相信和顺服。熟悉传统、拥有职分不能代替信心；律法不是自义凭据，乃揭露我们的需要。神在基督里成全应许，圣灵使人领受；蒙恩的人以诚实与忠贞回应。')+card('圣经神学闭环：话语 → 拒绝 → 真理见证 → 更新','约翰由耶稣说话的权柄，引向他由父差来的身份；人的拒绝引向审判，也显明我们需要恩典。十架与复活不是本段已发生的事件，却是整卷叙事给出的救赎归宿；圣灵使主的道成为心中的光。')+'</div><div class="grid three">'+card('Ⅰ 罪｜我保护自己的宝座','把不舒服的事实叫攻击，把提醒我的人叫敌人，把熟悉圣经当成不必再听神。')+card('Ⅱ 救赎｜他担当我的罪债','基督的义是称义根据，圣灵的更新使人信靠；不是我先变得足够谦卑才配蒙接纳。')+card('Ⅲ 感恩｜我重新学习受教','听完、查实、说真话、具体更正、在婚约与群体生活中忠贞，因蒙恩而顺服。')+'</div><p>全然败坏不等于没有理性能力、每项判断都错或人人同样恶；它指罪影响人的各部分，使人不能靠自己恢复与神和好的关系。主使用圣道、教导与查验，也藉圣灵更新人心。我们应尊重真实知识与审慎推理，同时拒绝把知识当作救主。</p>')
body+=section('confessions','三项联合信条的坐标','共同告白，<br>使我们也受查验','<p>以下是原创条文导读；随后逐字短引另列。圣经是最高准则，信经信条是服从圣经的教会共同认信，讲章也须接受经文查验。</p>'+''.join('<article class="confession"><h3>'+E(x['name'])+'</h3><span class="tag">'+E(x['reference'])+'</span>'+paras([x['explanation']])+'<a href="'+E(x['url'])+'" target="_blank" rel="noopener">指定网站原文 ↗</a></article>'for x in S['confessions'])+'<div class="grid three">'+''.join('<article class="small-card source-quote"><span class="tag">'+E(x['name'])+' · '+E(x['reference'])+'</span><blockquote>'+E(x['text'])+'</blockquote><a href="'+E(x['url'])+'" target="_blank" rel="noopener">逐字出处 ↗</a></article>'for x in S['quotes']if x['name']not in ['使徒信经','尼西亚信经','亚他那修信经'])+'</div>')
body+=section('creeds','三大普世信经的守护','我们信靠的，<br>是真实的神与真实的救主','<div class="grid three">'+''.join('<article class="small-card"><h3>'+E(x['name'])+'</h3><p class="caption">'+E(x['date'])+'</p>'+paras([x['context'],x['focus'],x['connection']])+'<div class="memory-line">'+E(x['memory'])+'</div><a href="'+E(x['url'])+'" target="_blank" rel="noopener">CCI 全文入口 ↗</a></article>'for x in S['comparisons'])+'</div><div class="grid three">'+''.join('<article class="small-card source-quote"><h3>'+E(x['name'])+'</h3><blockquote>'+E(x['text'])+'</blockquote><a href="'+E(x['url'])+'" target="_blank" rel="noopener">核对原文 ↗</a></article>'for x in S['quotes']if x['name']in ['使徒信经','尼西亚信经','亚他那修信经'])+'</div><p>三份信经以不同密度服事同一信仰：救恩历史的简明叙事、三一神性的清晰宣告、基督二性一位的精确守护。它们不是代替圣经的权威圈子，而是教会公开承认自己如何领受圣经，好让教导可以被查验。</p><div class="note">本站所称原文，是指定网站的中文译文，不冒称希腊文或拉丁文原典。六份文本只作逐字短引与原站全文链接，不重印全文；所有解释与记忆句均标为原创导读。</div>')
body+=section('memory','思维导图与记忆工具','两次回应，<br>四步归回','''<div class="mindmap" role="img" aria-label="罪的自欺到福音更新的思维导图"><div class="mind-center">你是否也愿受真理纠正？</div><div class="mind-branches"><div><span>对差役</span><b>见证被压下</b><p>先贴迷惑标签<br>再以地位代证据</p></div><div><span>对尼哥底母</span><b>律法被架空</b><p>不回应公义问题<br>转向地域与身份</p></div><div><span>在基督里</span><b>心思被更新</b><p>不是靠自辩得接纳<br>因蒙接纳肯认错</p></div></div></div><div class="memory-banner">先听事实，再查圣言；<br>认罪归主，感恩受教。</div><div class="grid three"><button class="flash" data-answer="47–49节：把见证者叫受迷惑，以权威圈子代替证据，并轻看需要受教的群众。">① 对差役怎样回应？<span>点击揭晓</span></button><button class="flash" data-answer="50–52节：避开先听后断的要求，用地域标签羞辱提问者，给查考预设不可改的结论。">② 对尼哥底母呢？<span>点击揭晓</span></button><button class="flash" data-answer="基督担当自义与不信的罪债，圣灵更新人心；我因蒙恩，能诚实倾听、认罪更正、忠贞生活。">③ 出路在哪里？<span>点击揭晓</span></button></div><h3>30秒复述</h3><p>他们听见见证，先问是谁；他们听见律法，先问哪边。我也会为保护自己而拒绝真理。基督为罪人舍命，圣灵使心更新；所以我先听、再查、认罪、受教。</p><p class="caption">今天复述两点；明天闭卷说出45–49与50–52两段结构；七天后回顾一次真实争执。记忆句是原创概括，不是经文或信条引文。</p>''')
